import{_ as t,o as d,c as o,ak as a}from"./chunks/framework.WEfAUR5x.js";const u=JSON.parse('{"title":"Admin API","description":"","frontmatter":{},"headers":[],"relativePath":"guide/api.md","filePath":"guide/api.md","lastUpdated":1780002933000}'),r={name:"guide/api.md"};function c(i,e,n,s,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="admin-api" tabindex="-1">Admin API <a class="header-anchor" href="#admin-api" aria-label="Permalink to “Admin API”">​</a></h1><p>The admin API lives under <code>/api/v1/*</code> and is consumed by the web UI. You can also call it programmatically — either with a session cookie (after logging in) or with an API token that holds the right capability.</p><p>This page is a high-level map. For the consumer-facing read endpoint, see <a href="./consuming-data">Consuming data</a>.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to “Authentication”">​</a></h2><p>Two equivalent options:</p><ul><li><strong>Session cookie</strong> — set automatically after you log in to the UI. Useful when scripting against your own browser session.</li><li><strong>Bearer token</strong> — <code>Authorization: Bearer pika_...</code>. The token must hold a capability that covers the requested operation.</li></ul><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Token capabilities for admin operations are different from path scopes used on <code>/data/*</code>. A token holds a list of capabilities (<code>files.read</code>, <code>settings.manage</code>, …). The list is set when the token is created.</p></div><h2 id="discovery" tabindex="-1">Discovery <a class="header-anchor" href="#discovery" aria-label="Permalink to “Discovery”">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Capability</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/healthz</code></td><td><em>(public)</em></td><td>Liveness probe. Returns <code>OK</code>.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/info</code></td><td><em>(public)</em></td><td>Server metadata, version, current user identity, effective capabilities, encryption-config warning flag.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/key/status</code></td><td><em>(public)</em></td><td>Server-key state (initialized / locked / unlocked). Allowed while the server is locked.</td></tr></tbody></table><p><code>/api/v1/info</code> is the discovery endpoint — the UI calls it on every load to decide which sections to render, and scripts can use it to feature-detect.</p><h2 id="configuration-data-plane" tabindex="-1">Configuration data plane <a class="header-anchor" href="#configuration-data-plane" aria-label="Permalink to “Configuration data plane”">​</a></h2><p>These operate on the persisted config tree.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Capability</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/folder</code>, <code>/folder/*</code></td><td><code>files.read</code></td><td>List folders / contents.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/folder/*</code></td><td><code>files.write</code></td><td>Create a folder.</td></tr><tr><td><code>DELETE</code></td><td><code>/api/v1/folder/*</code></td><td><code>files.write</code></td><td>Delete a folder.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/file/*</code></td><td><code>files.read</code></td><td>Read a config file. Supports <code>?variant=</code> and <code>?version=</code>.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/file/*</code></td><td><code>files.write</code></td><td>Create or update a config file (creates a new version).</td></tr><tr><td><code>DELETE</code></td><td><code>/api/v1/file/*</code></td><td><code>files.write</code></td><td>Delete a config file.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/versions/*</code></td><td><code>files.read</code></td><td>List versions of a file.</td></tr><tr><td><code>PATCH</code></td><td><code>/api/v1/versions/*</code></td><td><code>files.write</code></td><td>Set / clear the semver tag on a specific version.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/variants/*</code></td><td><code>files.read</code></td><td>List the variants of a file.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/render/*</code></td><td><code>files.read</code></td><td>Resolve a file (inheritance + variant + version) and return the merged document.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/convert</code></td><td><code>files.read</code></td><td>Convert content between JSON / YAML / TOML.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/search?q=...</code></td><td><code>files.read</code></td><td>Full-text search across configs (Server-Sent Events stream).</td></tr></tbody></table><h2 id="consumer-endpoints" tabindex="-1">Consumer endpoints <a class="header-anchor" href="#consumer-endpoints" aria-label="Permalink to “Consumer endpoints”">​</a></h2><p>Reachable on the same admin port. To expose configuration data on a separate port (no Bearer required, custom shape, optional request-rule pre-stage), configure an <a href="./endpoints">Endpoint</a> instead.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Capability</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/data/*</code></td><td><code>files.read</code> <em>(scope-gated)</em></td><td>Resolved config — see <a href="./consuming-data">Consuming data</a>.</td></tr></tbody></table><h2 id="external-resources" tabindex="-1">External resources <a class="header-anchor" href="#external-resources" aria-label="Permalink to “External resources”">​</a></h2><p>Browse and operate on configured external backends (Vault, Consul, etcd, AWS, Azure, GCP, Kubernetes, HTTP). All endpoints are gated on <code>external.*</code> because exposing them returns or mutates third-party secrets.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Capability</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/external/resources</code></td><td><code>external.read</code></td><td>List configured external resources.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/external/{name}/paths</code></td><td><code>external.read</code></td><td>Browse the namespace of one resource.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/external/{name}/test</code></td><td><code>external.read</code></td><td>Probe connectivity / credentials for one resource.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/external/{name}/read</code></td><td><code>external.read</code></td><td>Read one entry by path (body carries the path; <code>*</code> wildcard not viable in middle-segment routing).</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/external/{name}/write</code></td><td><code>external.write</code></td><td>Create / update one entry.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/external/{name}/delete</code></td><td><code>external.write</code></td><td>Delete one entry.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/external/{name}/versions</code></td><td><code>external.read</code></td><td>List historical versions (KV backends that support it).</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/external/{name}/version</code></td><td><code>external.read</code></td><td>Read a specific version of an entry.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/external/{name}/search</code></td><td><code>external.read</code></td><td>Search within the resource.</td></tr></tbody></table><h2 id="users-permissions-tokens" tabindex="-1">Users, permissions, tokens <a class="header-anchor" href="#users-permissions-tokens" aria-label="Permalink to “Users, permissions, tokens”">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Capability</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET</code>,<code>POST</code>,<code>PATCH</code>,<code>DELETE</code></td><td><code>/api/v1/users[/*]</code></td><td><code>users.manage</code></td><td>User CRUD.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/users-kick/*</code></td><td><code>users.manage</code></td><td>Force-logout a user (invalidates their sessions).</td></tr><tr><td><code>DELETE</code></td><td><code>/api/v1/users-totp/*</code></td><td><code>users.manage</code></td><td>Admin reset of a user&#39;s TOTP enrolment.</td></tr><tr><td><code>GET</code>,<code>POST</code>,<code>PATCH</code>,<code>DELETE</code></td><td><code>/api/v1/permissions[/*]</code></td><td><code>permissions.manage</code></td><td>Permission bundle CRUD.</td></tr><tr><td><code>GET</code>,<code>PUT</code></td><td><code>/api/v1/user-permissions/*</code></td><td><code>permissions.manage</code></td><td>Read / replace a user&#39;s bundle assignments.</td></tr><tr><td><code>GET</code>,<code>POST</code>,<code>DELETE</code>,<code>PATCH</code></td><td><code>/api/v1/tokens[/*]</code></td><td><code>tokens.manage</code></td><td>API token CRUD.</td></tr></tbody></table><h2 id="server-administration" tabindex="-1">Server administration <a class="header-anchor" href="#server-administration" aria-label="Permalink to “Server administration”">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Capability</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET</code>,<code>POST</code></td><td><code>/api/v1/settings</code></td><td><code>settings.manage</code></td><td>Read / patch the entire settings document.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/key/initialize</code></td><td><code>settings.manage</code></td><td>Opt in to at-rest encryption (first-time setup).</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/key/unlock</code></td><td><code>settings.manage</code></td><td>Unlock the server after a restart by supplying the master key.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/key/lock</code></td><td><code>settings.manage</code></td><td>Manually re-lock the server without restarting.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/key/rotate</code></td><td><code>settings.manage</code></td><td>Rotate the server encryption key (current → new).</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/tls/status</code></td><td><code>settings.manage</code></td><td>Inspect active HTTPS policy and certificate expiry.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/tls/self-signed</code></td><td><code>settings.manage</code></td><td>Generate and activate a managed self-signed certificate.</td></tr><tr><td><code>PUT</code></td><td><code>/api/v1/tls/manual</code></td><td><code>settings.manage</code></td><td>Upload and activate a PEM certificate / key pair.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/tls-generate</code></td><td><code>settings.manage</code></td><td>Generate a TLS certificate / key pair without activating it.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/ssh-keygen</code></td><td><code>settings.manage</code></td><td>Generate an SSH key pair (used by external resources that require key-based auth, e.g. Git over SSH).</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/cluster/status</code></td><td><code>settings.manage</code></td><td>Runtime cluster role, quorum, leader, visible alan peers.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/public-endpoints/status</code></td><td><code>settings.manage</code></td><td>Runtime state of each configured Endpoint listener.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/public-endpoints/test-rules</code></td><td><code>settings.manage</code></td><td>Dry-run draft Endpoint request rules and return a trace.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/public-endpoints/{id}/test</code></td><td><code>settings.manage</code></td><td>Synthetic probe against a saved Endpoint.</td></tr><tr><td><code>GET</code>,<code>POST</code></td><td><code>/api/v1/backup[/info]</code></td><td><code>settings.manage</code></td><td>Export / inspect / import a full backup archive.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/user-sync/status</code></td><td><code>settings.manage</code></td><td>Last-run report for every configured user-sync source.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/user-sync/run/*</code></td><td><code>settings.manage</code></td><td>Trigger a one-shot user-sync run.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/user-sync/test/*</code></td><td><code>settings.manage</code></td><td>Dry-run a user-sync source — no writes performed.</td></tr></tbody></table><h2 id="per-user-endpoints" tabindex="-1">Per-user endpoints <a class="header-anchor" href="#per-user-endpoints" aria-label="Permalink to “Per-user endpoints”">​</a></h2><p>Reserved under <code>/api/v1/me/*</code>. Every authenticated user can read and modify their own resources; no extra capability is required.</p><table tabindex="0"><thead><tr><th>Group</th><th>Routes</th></tr></thead><tbody><tr><td><strong>Preferences</strong></td><td><code>GET / PUT / DELETE /api/v1/me/preferences</code></td></tr><tr><td><strong>Passkeys</strong></td><td><code>POST /me/passkeys/begin</code>, <code>/finish</code>; <code>GET /me/passkeys</code>; <code>PATCH / DELETE /me/passkeys/*</code></td></tr><tr><td><strong>TOTP</strong></td><td><code>GET /me/totp</code>; <code>POST /me/totp/begin</code>, <code>/finish</code>, <code>/recovery-codes</code>; <code>DELETE /me/totp</code></td></tr><tr><td><strong>Personal vault</strong></td><td><code>GET /me/vault/status</code>, <code>/account</code>; <code>POST /me/vault/setup</code>, <code>/unlock-check</code>, <code>/rotate-password</code>, <code>/recovery-kit</code>; <code>PUT /me/vault/session-lock</code>; <code>DELETE /me/vault</code></td></tr><tr><td><strong>Vault items</strong></td><td><code>GET / POST /me/vault/items</code>; <code>GET / PUT / DELETE /me/vault/items/*</code>; <code>POST /me/vault/items-restore/*</code>, <code>/items-use/*</code>; <code>GET /me/vault/items-versions/*</code></td></tr></tbody></table><h2 id="authentication-endpoints" tabindex="-1">Authentication endpoints <a class="header-anchor" href="#authentication-endpoints" aria-label="Permalink to “Authentication endpoints”">​</a></h2><p>Provided by the <a href="https://rakunlabs.github.io/ada/" target="_blank" rel="noreferrer">ada</a> auth manager — paths are stable but the strategies behind them are configured at runtime under <strong>Settings → Authentication</strong>.</p><table tabindex="0"><thead><tr><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET /login/info</code></td><td>Public — discover enabled strategies and login UI metadata. Allowed while locked.</td></tr><tr><td><code>GET /login/me</code></td><td>Current session — username, capabilities, MFA state. Returns 401 when not signed in.</td></tr><tr><td><code>POST /login/pass/{strategy}</code></td><td>Password-style strategies (<code>local</code>, <code>ldap</code>, etc.). Rate-limited by <code>login_guard</code>.</td></tr><tr><td><code>GET /login/{strategy}</code></td><td>OAuth2 / OIDC redirect start.</td></tr><tr><td><code>POST /login/register/{strategy}</code></td><td>Self-registration (when enabled by the strategy).</td></tr><tr><td><code>POST /logout</code></td><td>Invalidates the current session.</td></tr></tbody></table><h2 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to “Conventions”">​</a></h2><ul><li>All write endpoints accept JSON request bodies and return JSON responses.</li><li>4xx responses include a <code>{ &quot;message&quot;: &quot;...&quot; }</code> body.</li><li>Long-running operations (search, backup export) stream over Server-Sent Events.</li><li>When the server is locked, all endpoints except the discovery group and <code>/login/*</code> / <code>/api/v1/key/{status,unlock}</code> return <code>503 Service Unavailable</code> with <code>X-Pika-Locked: true</code>. See <a href="./encryption">Encryption</a>.</li></ul>',31)])])}const m=t(r,[["render",c]]);export{u as __pageData,m as default};
